create table "public"."learning_paystack_test_fixtures" (
  "id"                  bigint                   generated by default as identity not null,
  "course_id"           bigint                   not null,
  "tester_id"           uuid                     not null,
  "status"              text                     not null default 'active'::text,
  "expires_at"          timestamp with time zone not null,
  "activated_at"        timestamp with time zone not null default now(),
  "activated_by"        uuid                     not null,
  "closed_at"           timestamp with time zone,
  "closed_by"           uuid,
  "close_reason"        text,
  "previous_fixture_id" bigint,
  constraint "learning_paystack_test_fixtures_course_id_fkey" foreign key (course_id) references public.learning_courses(id) on delete restrict,
  constraint "learning_paystack_test_fixtures_expiry_check" check ((expires_at > activated_at)),
  constraint "learning_paystack_test_fixtures_lifecycle_check"
    check ((((status = 'active'::text) AND (closed_at IS NULL) AND (closed_by IS NULL) AND (close_reason IS NULL)) OR ((status = 'closed'::text) AND (closed_at IS
    NOT NULL) AND (closed_by IS NOT NULL) AND ((char_length(btrim(close_reason)) >= 3) AND (char_length(btrim(close_reason)) <= 500))))),
  constraint "learning_paystack_test_fixtures_pkey" primary key (id),
  constraint "learning_paystack_test_fixtures_previous_fixture_id_fkey" foreign key (previous_fixture_id) references public.learning_paystack_test_fixtures(id) on delete restrict,
  constraint "learning_paystack_test_fixtures_previous_fixture_not_self_check" check (((previous_fixture_id IS NULL) OR (previous_fixture_id <> id))),
  constraint "learning_paystack_test_fixtures_status_check" check ((status = ANY (ARRAY['active'::text, 'closed'::text]))),
  constraint "learning_paystack_test_fixtures_activated_by_fkey" foreign key (activated_by) references public.profiles(id) on delete restrict,
  constraint "learning_paystack_test_fixtures_closed_by_fkey" foreign key (closed_by) references public.profiles(id) on delete restrict,
  constraint "learning_paystack_test_fixtures_tester_id_fkey" foreign key (tester_id) references public.profiles(id) on delete restrict
);

alter table "public"."learning_paystack_test_fixtures"
  enable row level security;

create index learning_paystack_test_fixtures_course_history_idx on public.learning_paystack_test_fixtures using btree (course_id, activated_at desc, id desc);

create unique index learning_paystack_test_fixtures_one_active_key on public.learning_paystack_test_fixtures using btree (status)
  where (status = 'active'::text);

create unique index learning_paystack_test_fixtures_one_successor_key on public.learning_paystack_test_fixtures using btree (previous_fixture_id)
  where (previous_fixture_id is not null);

create index learning_paystack_test_fixtures_tester_idx on public.learning_paystack_test_fixtures using btree (tester_id, expires_at desc);

create trigger protect_paystack_test_fixture_history
  before insert or update on public.learning_paystack_test_fixtures
  for each row
  execute function public.protect_paystack_test_fixture_history();

grant delete, insert, maintain, references, select, trigger, truncate, update on table "public"."learning_paystack_test_fixtures" to "postgres", "service_role";
